def solve(words):
    result = []
    for word in words:
        count = 0
        for i, char in enumerate(word):
            pos_in_word = i + 1
            if 'a' <= char <= 'z':
                alphabet_pos = ord(char) - ord('a') + 1
            elif 'A' <= char <= 'Z':
                alphabet_pos = ord(char) - ord('A') + 1
            else:
                continue
            if pos_in_word == alphabet_pos:
                count += 1
        result.append(count)
    return result
